b1+='<div style="position:absolute;left:-140px;top:760px;width:1040px;height:950px;transform:rotate(-12deg);clip-path:polygon(22% 4%,80% 0,96% 25%,100% 62%,80% 96%,27% 100%,2% 70%,0 28%);background:#111">'+img('ear_source.jpg','width:100%;height:100%;object-fit:cover;object-position:48% 51%;filter:grayscale(1) contrast(1.16)')+texture('photocopy_browser.jpg',.22,'screen')+'</div>'
b1+='<div style="position:absolute;left:715px;top:1120px;transform:rotate(-8deg);width:630px;height:240px;background:#f5f0e7;padding:20px;box-shadow:0 15px 20px #0003">'+img('microphone_source.jpg','width:100%;height:100%;object-fit:cover;object-position:right center;filter:grayscale(1)')+texture('paper_material.jpg',.28)+'</div>'
b1+='<svg style="position:absolute;inset:0" viewBox="0 0 1080 1920"><path d="M565 1270 C760 1330 820 1490 787 1540" fill="none" stroke="#f2e9d9" stroke-width="9"/><path d="M764 1509L788 1548L811 1517" fill="none" stroke="#f2e9d9" stroke-width="8"/></svg>'
b1+=label('YOU HEAR','left:90px;top:1600px;background:#ffd92f;color:#161819;padding:12px 18px;transform:rotate(-3deg)')+label('AIR + BODY','left:89px;top:1670px;color:#161819;font-size:35px;letter-spacing:0')+label('A MIC RECORDS','left:682px;top:1510px;width:270px;color:#fff')+label('AIR','left:690px;top:1590px;color:#fff;font-size:78px')
b1+=label('Two routes to the same ears.<br>One is missing on playback.','left:80px;top:1790px;width:730px;font-size:28px;letter-spacing:0')+texture('fiber_browser.jpg',.10)
# B: photo-led source field with spine specimen
b2='<div class="art" style="background:#11233b;color:#f5f0e7">'+img('earth_browser.png','position:absolute;left:150px;top:1065px;width:1370px;height:1370px;object-fit:contain;filter:contrast(1.12)')
b2+='<div style="position:absolute;inset:0;background:linear-gradient(170deg,transparent 55%,#09152288 100%)"></div>'+title('Less load.<br>More <i>space.</i>','left:80px;top:210px;font-size:137px;z-index:6')
b2+='<div style="position:absolute;left:30px;top:660px;width:355px;height:920px;background:#f5f0e7;transform:rotate(-8deg);box-shadow:15px 25px 30px #0007;clip-path:polygon(2% 0,96% 1%,100% 7%,99% 96%,94% 100%,0 98%)">'+texture('paper_material.jpg',.62)+img('spine_photo_cutout.png','position:absolute;left:46px;top:40px;width:263px;height:758px;object-fit:contain')+label('SPINE MODEL','left:42px;top:823px;color:#132339;font-size:23px')+'</div>'
b2+=img('astronaut_cutout.png','position:absolute;left:290px;top:588px;width:890px;height:970px;object-fit:contain;transform:rotate(6deg);filter:drop-shadow(8px 18px 12px #0008)')
b2+='<svg style="position:absolute;inset:0" viewBox="0 0 1080 1920"><path d="M159 772C162 635 270 587 362 596" fill="none" stroke="#ffd827" stroke-width="7"/><path d="M342 578L368 597L340 615" fill="none" stroke="#ffd827" stroke-width="7"/></svg>'
b2+=label('UNLOADING','left:100px;top:585px;background:#ffd827;padding:11px 20px;transform:rotate(-4deg);color:#132339;font-size:29px')+label('In microgravity, the spine<br>can lengthen temporarily.','left:80px;top:1610px;font-size:37px;letter-spacing:0;width:820px')+label('Photographic composition · model, not a scan<br>NASA astronaut + satellite composite / John Campbell model','left:80px;top:1780px;font-size:22px;letter-spacing:0;font-weight:550')+texture('photocopy_browser.jpg',.20,'screen')
# C: dark optical field; photograph is foreground, type wraps around it
b3='<div class="art" style="background:#0d121a;color:#f5f0e7">'+texture('plastic_browser.jpg',.25,'screen')
b3+=title('One beam.','left:78px;top:244px;font-size:137px;z-index:5')
b3+='<div style="position:absolute;left:110px;top:540px;width:955px;height:980px;transform:rotate(7deg);border:16px solid #f5f0e7;box-shadow:-20px 24px 0 #ffd928;clip-path:polygon(0 3%,98% 0,100% 97%,2% 100%)">'+img('prism.jpg','position:absolute;width:100%;height:100%;object-fit:cover;object-position:50% 43%')+'</div>'
b3+=label('WHITE LIGHT','left:83px;top:429px;background:#f5f0e7;color:#111a25;padding:16px 22px;transform:rotate(-5deg);font-size:37px')
b3+=title('Many<br><i>colours.</i>','left:78px;top:1444px;font-size:158px;z-index:6')
b3+=label('A prism separates light by wavelength.','left:80px;top:1790px;font-size:29px;letter-spacing:0')+label('Actual prism photograph · Han-Kwang / CC BY 2.5','left:80px;top:1850px;font-size:21px;letter-spacing:0')
# D: full-bleed image first, typography occupies the missing-paper space below
b4='<div class="art" style="background:#f34924;color:#152032">'+texture('fiber_browser.jpg',.28)
b4+='<div style="position:absolute;left:-110px;top:225px;width:1290px;height:830px;transform:rotate(-6deg);background:#f5f0e7;box-shadow:0 25px 0 #132338">'+img('eye.jpg','position:absolute;left:0;top:0;width:1290px;height:830px;object-fit:cover;object-position:center 53%;filter:grayscale(1) contrast(1.13)')+ '<div style="position:absolute;left:92px;top:0;width:215px;height:830px;background:#f5f0e7;clip-path:polygon(9% 0,95% 0,88% 20%,100% 46%,86% 67%,100% 100%,0 100%,9% 72%,0 48%,12% 28%)">'+texture('paper_material.jpg',.7)+'</div></div>'
b4+=label('THE BLIND SPOT','left:83px;top:1114px;background:#ffdc2b;padding:14px 18px;color:#132338;transform:rotate(-3deg);font-size:32px')
b4+=title('Your brain<br>finishes<br>the <i>picture.</i>','left:80px;top:1250px;font-size:149px;z-index:8')
b4+=label('Missing print strip = visual metaphor.<br>The blind spot is on the retina, not the iris.','left:80px;top:1790px;font-size:25px;letter-spacing:0;color:#132338')
boards=[b1,b2,b3,b4]
briefs=[('01 — Hearing your own voice','A dominant cropped ear and a separate microphone print make the two listening routes visible. Photo slicing and scale replace the centered postcard.','Ear: Travis Isaacs / CC BY 2.0. Microphone: Anonimski / CC0.'),('02 — The unloaded spine','A real model anchors the science; the astronaut and oversized Earth establish context. Unequal photographic layers and a yellow attention mark support the relationship.','NASA imagery / John Campbell spine model, CC BY 2.0. Editorial composite.'),('03 — White light','The physical experiment is the evidence. The spectrum stays photographic and retains its colours; the surrounding print layout creates the visual contrast.','Han-Kwang prism photo / CC BY 2.5. Crop/rotation/print treatment.'),('04 — The blind spot','A missing piece of the print makes absence visible. It is explicitly a metaphor; the original iris remains intact.','Eye: Kookaaa / CC0. Crop/grayscale/print-strip metaphor.')]
for i in range(4):boards[i]+=f'<div class="folio">CURIO BUREAU / SCIENCE</div><div class="no">0{i+1}</div><div class="ink"></div><div class="safe"><span>Future captions: 42–58% · layout review only</span></div></div>'
items=''.join(f'<section class="item" data-board="{i+1}"><div class="viewport">{b}</div><div class="caption"><b>{briefs[i][0]}</b>{briefs[i][1]}<span>{briefs[i][2]}</span></div></section>' for i,b in enumerate(boards))
script='''const items=[...document.querySelectorAll('.item')];function fit(){for(const el of items){el.querySelector('.art').style.transform='scale('+el.querySelector('.viewport').clientWidth/1080+')'}}function choose(n){document.body.classList.toggle('single',n>0);items.forEach((e,i)=>e.classList.toggle('active',n===i+1));document.querySelectorAll('[data-select]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.select)===n));fit()}document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.select)));document.querySelector('#safe').onclick=()=>{document.body.classList.toggle('show-safe');document.querySelector('#safe').setAttribute('aria-pressed',document.body.classList.contains('show-safe'))};new ResizeObserver(fit).observe(document.body);Promise.all([document.fonts.ready,...[...document.images].map(i=>i.decode())]).then(()=>{fit();window.artReady=true});const initial=Number(new URLSearchParams(location.search).get('board')||0);choose(initial);'''
header='<header><p style="letter-spacing:3px;font-size:11px">CURIO BUREAU · ART DIRECTION LAB</p><h1>Four visual arguments.</h1><p>Static artwork for owner review. Judge image choice, composition, typography and material craft before motion. These are original design studies, not approved channel templates.</p><nav class="tools">'+''.join(f'<button data-select="{n}" aria-pressed="false">{s}</button>' for n,s in [(0,'All four'),(1,'Voice'),(2,'Space'),(3,'Light'),(4,'Vision')])+'<button id="safe" aria-pressed="false">Caption guide</button></nav></header>'
notices=''.join('<h3>'+p.name+'</h3><pre style="white-space:pre-wrap">'+__import__('html').escape(p.read_text())+'</pre>' for p in (root/'font_notices').glob('*.txt'))
rights='<footer style="max-width:1052px;margin:0 auto 40px;padding:24px;color:#bbb;font-size:12px"><details><summary>Image credits and font licenses</summary><p>Travis Isaacs: Ear, CC BY 2.0. John Campbell: Spine model, CC BY 2.0. Han-Kwang: Light through prism, CC BY 2.5. Anonimski: Microphone, CC0. Kookaaa: Eye, CC0. NASA: astronaut and VIIRS Earth montage; NASA imagery-use guidance applies. Changes: crops, masks, grayscale where shown, composition and print treatment. No endorsement implied.</p><p><a style="color:inherit" href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a> · <a style="color:inherit" href="https://creativecommons.org/licenses/by/2.5/">CC BY 2.5</a> · <a style="color:inherit" href="https://creativecommons.org/publicdomain/zero/1.0/">CC0</a></p>'+notices+'</details></footer>'
html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Curio Bureau — Static Art Review</title><style>'+fonts+css+'</style>'+header+'<main class="gallery">'+items+'</main>'+rights+'<script>'+script+'</script></html>'
(root/'deliverables/Curio_Bureau_Static_Art_Review.html').write_text(html)
(root/'layout.css').write_text(css)
(root/'boards.json').write_text(json.dumps({'briefs':briefs,'logical_dimensions':[1080,1920],'status':'OWNER_REVIEW_PENDING','animation':False},indent=2))
print('built',len(html))
